    <div class="stat-item">
      <div class="stat-value">4.3B</div>
      <div class="stat-label">Lbs of Food Rescued</div>
      <div class="stat-sub">good food saved from waste</div>
    </div>
    <div class="stat-item">
      <div class="stat-value">60K+</div>
      <div class="stat-label">Programs Operating</div>
      <div class="stat-sub">distributing free food nationwide</div>
    </div>
    <div class="stat-item">
      <div class="stat-value">200+</div>
      <div class="stat-label">Food Banks</div>
      <div class="stat-sub">in the Feeding America network</div>
    </div>
  </div>

  <!-- Pillars -->
  <div class="pillars">
    <div class="section-title">How We Unite Communities</div>
    <div class="pillars-grid">
      <div class="pillar-card">
        <div class="pillar-title">🔬 Research-Driven Insights</div>
        <div class="pillar-desc">Listening to neighbors facing hunger and sharing their stories and ideas to shape real solutions.</div>
      </div>
      <div class="pillar-card">
        <div class="pillar-title">🌐 Local Roots, National Scale</div>
        <div class="pillar-desc">Food bank leaders are passionate community members. Local wisdom becomes national action every day.</div>
      </div>
      <div class="pillar-card">
        <div class="pillar-title">🏗️ Nationwide Infrastructure</div>
        <div class="pillar-desc">One of the nation's most effective food networks — moving food quickly and reliably to where it's needed most.</div>
      </div>
      <div class="pillar-card">
        <div class="pillar-title">🥗 Nutrition for Every Plate</div>
        <div class="pillar-desc">Making nutritious food more accessible so everyone can lead fuller, healthier lives.</div>
      </div>
    </div>
  </div>

  <!-- Conversion Metric -->
  <div class="conversion-metric">
    <div class="metric-label">Your Donation Creates Impact</div>
    <div class="metric-value">$1 = 10 MEALS</div>
    <div class="metric-desc">Every dollar provides at least 10 meals to neighbors in need</div>
  </div>

  <!-- CTAs -->
  <div class="cta-section">
    <div class="section-title">How You Can Make a Difference</div>
    <div class="cta-grid">
      <div class="cta-card">
        <div class="cta-icon">💝</div>
        <div class="cta-title">DONATE</div>
        <div class="cta-desc">Every $1 = 10 meals. Gifts are matched for a limited time to move fresh food fast.</div>
      </div>
      <div class="cta-card">
        <div class="cta-icon">📣</div>
        <div class="cta-title">ADVOCATE</div>
        <div class="cta-desc">Urge lawmakers to support community organizations helping neighbors facing hunger.</div>
      </div>
      <div class="cta-card">
        <div class="cta-icon">🎉</div>
        <div class="cta-title">FUNDRAISE</div>
        <div class="cta-desc">Inspire your community to come together and make a collective difference.</div>
      </div>
      <div class="cta-card">
        <div class="cta-icon">🙋</div>
        <div class="cta-title">VOLUNTEER</div>
        <div class="cta-desc">Sorting, packing, and distributing food takes many hands — including yours.</div>
      </div>
    </div>
  </div>

  <!-- Footer -->
  <div class="footer-bar">
    <div class="footer-text">Feeding America — Together We Can End Hunger</div>
    <div class="footer-url">feedingamerica.org</div>
  </div>
</div>
