const puppeteer = require('puppeteer');
const path = require('path');
const fs = require('fs');

async function renderPoster() {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();

  await page.setViewport({
    width: 1080,
    height: 1920,
    deviceScaleFactor: 2
  });

  const htmlPath = path.resolve(__dirname, 'hunger-crisis-poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for fonts and content to fully render
  await page.waitForTimeout(3000);

  const outputPath = path.resolve(__dirname, 'output', 'final_poster.png');

  await page.screenshot({
    path: outputPath,
    type: 'png',
    fullPage: true,
    omitBackground: false
  });

  console.log(`✅ Poster saved to ${outputPath}`);

  await browser.close();
}

renderPoster().catch(err => {
  console.error('Error:', err.message);
  process.exit(1);
});

